export interface SetField {
  /**
   * Path of the field ID to be modified. Nested fields can be specified using dot notation.
   */
  fieldPath: string
  action: 'SET_FIELD'
  value: any
}

export interface RemoveField {
  /**
   * Path of the field ID to be modified. Nested fields can be specified using dot notation.
   */
  fieldPath: string
  action: 'REMOVE_FIELD'
}

export interface IncrementField {
  /**
   * Path of the field ID to be modified. Nested fields can be specified using dot notation.
   */
  fieldPath: string
  action: 'INCREMENT_FIELD'
  value: any
}

export interface AppendToArray {
  /**
   * Path of the field ID to be modified. Nested fields can be specified using dot notation.
   */
  fieldPath: string
  action: 'APPEND_TO_ARRAY'
  value: any
}

export interface RemoveFromArray {
  /**
   * Path of the field ID to be modified. Nested fields can be specified using dot notation.
   */
  fieldPath: string
  action: 'REMOVE_FROM_ARRAY'
  value: any
}

export type FieldModification =
  | SetField
  | RemoveField
  | IncrementField
  | AppendToArray
  | RemoveFromArray
